import re
import unicodedata


def slugify(title: str) -> str:
    normalized = unicodedata.normalize("NFKD", title)
    without_marks = "".join(
        char for char in normalized
        if not unicodedata.category(char).startswith("M")
    )
    return re.sub(r"[^a-z0-9]+", "-", without_marks.lower()).strip("-")
```

